INSERT INTO products (id, name, description, base_price, target_demographic, status) VALUES ('SM-PRD-047', 'Quần Jogger Dù Unisex', 'Dáng quần thoải mái, dễ vận động và phù hợp từ mặc nhà đến những buổi ra ngoài nhanh gọn. Chi tiết hoàn thiện ưu tiên sự linh hoạt và cảm giác thoáng mát khi di chuyển.', 559000, 'UNISEX', 'ACTIVE') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, base_price = EXCLUDED.base_price, target_demographic = EXCLUDED.target_demographic, status = EXCLUDED.status, updated_at = CURRENT_TIMESTAMP;
