INSERT INTO products (id, name, description, base_price, target_demographic, status) VALUES ('SM-PRD-048', 'Quần Mặc Nhà Cotton Unisex', 'Dáng quần thoải mái, dễ vận động và phù hợp từ mặc nhà đến những buổi ra ngoài nhanh gọn. Đây là lựa chọn dễ chịu cho lịch mặc ưu tiên sự thư giãn và tiện dụng.', 339000, 'UNISEX', 'ACTIVE') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, base_price = EXCLUDED.base_price, target_demographic = EXCLUDED.target_demographic, status = EXCLUDED.status, updated_at = CURRENT_TIMESTAMP;
