INSERT INTO products (id, name, description, base_price, target_demographic, status) VALUES ('SM-PRD-049', 'Áo Thun Active Unisex', 'Áo thun cotton mềm nhẹ với phom dễ mặc, phù hợp đi học, đi làm hoặc phối nhiều lớp hằng ngày. Chi tiết hoàn thiện ưu tiên sự linh hoạt và cảm giác thoáng mát khi di chuyển.', 299000, 'UNISEX', 'ACTIVE') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, base_price = EXCLUDED.base_price, target_demographic = EXCLUDED.target_demographic, status = EXCLUDED.status, updated_at = CURRENT_TIMESTAMP;
