INSERT INTO products (id, name, description, base_price, target_demographic, status) VALUES ('SM-PRD-050', 'Áo Tank Top Essential Unisex', 'Phom gọn, co giãn tốt và phù hợp mặc riêng hoặc phối lớp trong những set đồ tối giản. Thiết kế tối giản giúp món đồ bền xu hướng và dễ lặp lại trong tủ đồ.', 219000, 'UNISEX', 'INACTIVE') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, base_price = EXCLUDED.base_price, target_demographic = EXCLUDED.target_demographic, status = EXCLUDED.status, updated_at = CURRENT_TIMESTAMP;
